    entry_requirements = '<table><tbody><tr><td><strong>English Proficiency</strong></td><td><ul><li>IELTS (Academic): 6.5 overall (no band lower than 6.0)</li><li>Pearson Test of English (Academic): 58 overall with no band lower than 50</li><li>TOEFL Internet-based test: 79 overall (Writing: 21, Listening: 12, Reading: 13, Speaking: 18)</li><li>Equivalent approved English test</li></ul></td></tr><tr><td><strong>Other</strong></td><td><ul><li>Articulation agreement: National Institute of Technology, Akashi College (2+1)</li><li>Exp: 28-July-24</li><li>Renewal in progress</li></ul></td></tr></tbody></table>',
    apply_form = 'https://handbook.monash.edu/2026/courses/F6003',
